// 用户名检测防抖定时器
let usernameCheckTimer = null;

// ===== L2897-L2980 renderEmployees =====
function renderEmployees() {
  const editing = state.employees.find((item) => item.id === state.editingEmployeeId);
  const filteredEmployees = state.employees.filter((item) => {
    const keyword = state.employeeSearch.trim().toLowerCase();
    if (keyword) {
      const target = [item.employeeCode, item.name, item.phone, item.loginUsername].join(" ").toLowerCase();
      if (!target.includes(keyword)) return false;
    }
    if (state.employeeStatusFilter && item.status !== state.employeeStatusFilter) return false;
    return true;
  });
  const activeEmployees = state.employees.filter((item) => item.status === "在职").length;
  const enabledUsers = state.employees.filter((item) => item.loginUsername).length;
  const totalAccounts = state.employees.reduce((sum, item) => sum + Number(item.accountCount || 0), 0);
  const pausedEmployees = state.employees.filter((item) => item.status !== "在职").length;
  return `
    <div class="page-header page-header-rich">
      <div>
        <h2>员工管理</h2>
        <p class="page-desc">先把员工和登录账号管清楚，后面作品、客资、完成情况才会跟着稳定沉淀。</p>
      </div>
      <div class="toolbar toolbar-end">
        <span class="tag">${filteredEmployees.length} / ${state.employees.length} 人</span>
      </div>
    </div>
    <section class="grid-4">
      ${stat("在职员工", activeEmployees, "当前状态为在职的员工数量。", "人员")}
      ${stat("已开通登录", enabledUsers, "已经可以直接登录员工端的人员数量。", "权限")}
      ${stat("名下账号总数", totalAccounts, "当前所有员工已绑定的账号总和。", "账号")}
      ${stat("离职 / 停用", pausedEmployees, "当前不在正常在职状态的员工数量。", "状态")}
    </section>
    <section class="grid-2">
      <div class="panel">
        <h3>${editing ? "编辑员工" : "新增员工"}</h3>
        <form id="employeeForm" class="form-grid">
          <input type="hidden" name="id" value="${editing?.id || ""}" />
          <input name="name" placeholder="员工姓名" value="${editing?.name || ""}" required />
          <input name="phone" placeholder="联系方式" value="${editing?.phone || ""}" />
          <input name="hireDate" type="date" value="${editing?.hireDate || ""}" />
          <select name="status">
            <option value="在职" ${editing?.status === "在职" ? "selected" : ""}>在职</option>
            <option value="离职" ${editing?.status === "离职" ? "selected" : ""}>离职</option>
            <option value="停用" ${editing?.status === "停用" ? "selected" : ""}>停用</option>
          </select>
          <div class="form-section-header full">登录账号设置</div>
          <div class="form-hint full">创建员工时可同时创建登录账号，员工可使用此账号登录系统。</div>
          <div class="input-wrapper full">
            <input
              name="loginUsername"
              placeholder="登录用户名"
              value="${editing?.loginUsername || ""}"
              oninput="handleUsernameInput(this)"
              ${editing?.loginUsername ? 'disabled' : ''}
            />
            <span id="usernameCheckStatus" class="check-status"></span>
          </div>
          <input
            name="loginPassword"
            type="password"
            placeholder="初始密码（留空则自动生成）"
            ${editing?.loginUsername ? 'disabled' : ''}
          />
          <input type="hidden" name="createLoginAccount" value="${editing?.loginUsername ? 'false' : 'true'}" />
          <div class="actions full">
            <button class="primary" type="submit" id="submitEmployeeBtn">${editing ? "保存员工" : "新增员工"}</button>
            ${editing ? `<button class="ghost js-cancel-employee" type="button">取消编辑</button>` : ""}
          </div>
        </form>
      </div>
    </section>
    <div class="panel">
      <div class="filters filters-toolbar management-toolbar">
        <input id="employeeSearchInput" placeholder="搜索员工姓名 / 编号 / 手机 / 登录账号" value="${state.employeeSearch}" />
        <select id="employeeStatusFilter">
          <option value="">全部状态</option>
          ${["在职", "离职", "停用"].map((item) => `<option value="${item}" ${state.employeeStatusFilter === item ? "selected" : ""}>${item}</option>`).join("")}
        </select>
      </div>
      <div class="table-wrap">
        <table>
          <thead><tr><th>编号</th><th>姓名</th><th>电话</th><th>入职时间</th><th>状态</th><th>登录账号</th><th>账号数</th><th>操作</th></tr></thead>
          <tbody>${filteredEmployees.length ? filteredEmployees.map((item) => `<tr><td>${item.employeeCode}</td><td><div class="cell-stack"><strong>${item.name}</strong><span class="muted">${item.phone || "未填写联系方式"}</span></div></td><td>${item.phone || "-"}</td><td>${item.hireDate || "-"}</td><td><span class="tag ${item.status === "在职" ? "" : "tag-soft"}">${item.status}</span></td><td>${item.loginUsername ? `<span class="tag tag-soft">${item.loginUsername}</span>` : "未创建"}</td><td>${item.accountCount}</td><td><div class="actions"><button class="ghost js-edit-employee" data-id="${item.id}">编辑</button><button class="ghost danger js-delete-employee" data-id="${item.id}">删除</button></div></td></tr>`).join("") : `<tr><td colspan="8"><div class="empty">当前筛选条件下没有员工。</div></td></tr>`}</tbody>
        </table>
      </div>
    </div>
  `;
}

// ===== 用户名实时检测 =====
async function handleUsernameInput(input) {
  const username = input.value.trim();
  const statusEl = document.getElementById("usernameCheckStatus");
  const submitBtn = document.getElementById("submitEmployeeBtn");

  // 清除之前的定时器
  if (usernameCheckTimer) {
    clearTimeout(usernameCheckTimer);
  }

  // 清除之前的错误样式
  input.classList.remove("input-error", "input-success");

  // 如果为空，清除状态
  if (!username) {
    statusEl.textContent = "";
    statusEl.className = "check-status";
    if (submitBtn) submitBtn.disabled = false;
    return;
  }

  // 显示检测中
  statusEl.textContent = "检测中...";
  statusEl.className = "check-status checking";

  // 防抖 500ms
  usernameCheckTimer = setTimeout(async () => {
    try {
      const result = await api(`/api/employees/check-username/${encodeURIComponent(username)}`);
      if (result.exists) {
        statusEl.textContent = "该用户名已存在";
        statusEl.className = "check-status error";
        input.classList.add("input-error");
        if (submitBtn) submitBtn.disabled = true;
        // 弹出错误提示
        showToast("error", "用户名重复", `用户名"${username}"已被使用，请更换一个用户名`);
      } else {
        statusEl.textContent = "用户名可用";
        statusEl.className = "check-status success";
        input.classList.add("input-success");
        if (submitBtn) submitBtn.disabled = false;
      }
    } catch (err) {
      statusEl.textContent = "检测失败";
      statusEl.className = "check-status error";
      input.classList.add("input-error");
      if (submitBtn) submitBtn.disabled = true;
      showToast("error", "检测失败", "无法检测用户名是否重复，请稍后重试");
    }
  }, 500);
}

// 全局标记：用户名是否可用
let usernameAvailability = { checked: false, available: false, username: "" };

// 重置用户名可用性标记
function resetUsernameAvailability() {
  usernameAvailability = { checked: false, available: false, username: "" };
}


// ===== L5380-L5398 submitEmployee =====
async function submitEmployee(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  const id = String(formData.get("id") || "");
  const loginUsername = String(formData.get("loginUsername") || "").trim();
  const loginPassword = String(formData.get("loginPassword") || "").trim();
  const createLoginAccount = formData.get("createLoginAccount") === "true";
  const editing = id ? state.employees.find((item) => item.id === id) : null;

  // 编辑模式下不允许修改用户名
  if (editing && editing.loginUsername) {
    // 不发送用户名相关字段
  }

  // 如果是新建且有用户名，必须先检测是否重复
  if (!id && loginUsername) {
    const statusEl = document.getElementById("usernameCheckStatus");

    // 检查是否正在检测中
    if (statusEl && statusEl.textContent === "检测中...") {
      showToast("warn", "请等待", "用户名检测中，请稍后再提交");
      return;
    }

    // 检查是否已经检测过且用户名不可用
    if (statusEl && statusEl.textContent === "该用户名已存在") {
      showToast("error", "用户名重复", "该用户名已被使用，请更换一个用户名。");
      return;
    }

    // 如果没有检测结果或检测失败，执行同步检测
    if (!statusEl || statusEl.textContent !== "用户名可用") {
      try {
        showToast("info", "检测中", "正在检测用户名是否可用...");
        const checkResult = await api(`/api/employees/check-username/${encodeURIComponent(loginUsername)}`);
        if (checkResult.exists) {
          showToast("error", "用户名重复", `用户名"${loginUsername}"已被使用，请更换一个用户名。`);
          if (statusEl) {
            statusEl.textContent = "该用户名已存在";
            statusEl.className = "check-status error";
          }
          const submitBtn = document.getElementById("submitEmployeeBtn");
          if (submitBtn) submitBtn.disabled = true;
          return;
        }
      } catch (err) {
        showToast("error", "检测失败", "无法检测用户名是否重复，请稍后重试。");
        return;
      }
    }
  }

  const body = {
    name: String(formData.get("name")).trim(),
    phone: String(formData.get("phone")).trim(),
    hireDate: String(formData.get("hireDate")).trim(),
    status: String(formData.get("status")).trim(),
  };

  // 只有在新建或用户名有变化时才发送登录账号信息
  if (!id && createLoginAccount && loginUsername) {
    body.loginUsername = loginUsername;
    body.loginPassword = loginPassword || undefined;
    body.createLoginAccount = true;
  } else if (!id && !loginUsername) {
    // 新建但未填写用户名，自动生成
    body.createLoginAccount = true;
  }

  try {
    await api(id ? `/api/employees/${id}` : "/api/employees", {
      method: id ? "PUT" : "POST",
      body: JSON.stringify(body)
    });
    state.editingEmployeeId = "";
    setFlash("success", id ? "员工信息已更新" : "员工已创建", "现在可以继续给员工绑定账号，或直接创建登录账号。");
    await loadData();
    renderApp();
  } catch (err) {
    showToast("error", id ? "更新失败" : "创建失败", err.message || "请稍后重试");
  }
}


// ===== L5430-L5437 deleteEmployee =====
async function deleteEmployee(id) {
  if (!window.confirm("确认删除该员工及其关联数据吗？")) return;
  try {
    await api(`/api/employees/${id}`, { method: "DELETE" });
    state.editingEmployeeId = state.editingEmployeeId === id ? "" : state.editingEmployeeId;
    await loadData();
    renderApp();
  } catch (err) {
    showToast("error", "删除失败", err.message || "请稍后重试");
  }
}

